Lemma ss_shad_app : forall lo hi a k', 0 <= lo -> hi <= 2 ^ 47 -> (hi <= PRB \/ PRB + 0x2000011000 <= lo) ->
  (forall k'' s', nth_error (sec Σ) k'' = Some s' -> In k'' [k] -> hi <= s_mb s' \/ s_mb s' + smsz (s_n s') <= lo) ->
